// 第7章：模様ができる理由と、模様の地図（T07 回収, T08, T15, T16, T17, T18）
// 前半は謎解き（近くは仲間を増やし、遠くは邪魔をする）と2つの実験、後半は F-k マップと再現チャレンジ。
// F-k マップ（RD.FkMap）は第8章のラボでも使う。
(function (RD) {
  const { h, p, step, note, more, teacher, card, math, fmt } = RD.ui;

  // ================================================================
  // F-k マップのデータ
  //   F = F0 + i×FS（i = 0..nF−1）、k = K0 + j×KS（j = 0..nK−1）の各マスで、
  //   RD.Sim（64×64、Du = 1, Dv = 0.5, dt = 0.8、種は 'random'）を 12000 コマ動かした結果。
  //   cls: マスごとの国（. 全滅 / U 一様 / o 水玉 / = しま・迷路 / # 穴あき / L 動きつづける）
  //   lv:  v の平均（0〜vmax を 16 段階、16進1文字）
  //   tiles: 模様のあるマスの見本（tile×tile、16 段階を4ビットずつ詰めて base64）
  //   作り方は tmp/chD/gen-map.mjs, encode-map.mjs（統括への報告を参照）
  // ================================================================
  const MAP = { F0: 0.01, FS: 0.0025, nF: 29, K0: 0.04, KS: 0.001, nK: 31, tile: 20, vmax: 0.4,
    cls: '........LLL.............................LLLLL.................ULL.......LLLLLL...............UUU.LLL.LLLLLLLLL..............UUUUU.LLLLLLLLLLLLL............UUUUUUUU..L=LLLLL.L.oL.........UUUUUUUUUU..====LLLLLooL.......UUUUUUUUUUUU.L=====LLooooo.....UUUUUUUUUUUUU.LL===LoooLooo....UUUUUUUUUUUUUUU.#=====oooooooooUUUUUUUUUUUUUUUU.#=====ooooooooUUUUUUUUUUUUUUUUUU#===LooooooooUUUUUUUUUUUUUUUUUUU=====ooLooooUUUUUUUUUUUUUUUUUUU#=====oLooooUUUUUUUUUUUUUUUUUUUU===L=oLooo.UUUUUUUUUUUUUUUUUUUU#==L==Loo..UUUUUUUUUUUUUUUUUUUU#=LL=Loo...UUUUUUUUUUUUUUUUUUUUU=LLLLo....UUUUUUUUUUUUUUUUUUUUU#LL=L.....UUUUUUUUUUUUUUUUUUUUU#==.......UUUUUUUUUUUUUUUUUUUUU#=........UUUUUUUUUUUUUUUUUUUUU..........UUUUUUUUUUUUUUUUUUUU...........UUUUUUUUUUUUUUUUUUU............UUUUUUUUUUUUUUUUU..............UUUUUUUUUUUUUUU................UUUUUUUUUUUUUU.................UUUUUUUUUUUU...................UUUUUUUUUUU....................',
    lv: '',
    tiles: '' };

  const COUNTRIES = {
    '.': { name: 'ウサギがいなくなる国', color: '#dfe7d2', desc: 'ウサギが全滅して、草だけの草原になります。' },
    U: { name: 'ウサギだらけの国', color: '#b99a74', desc: '草原じゅうが同じ濃さのウサギになり、模様はできません。' },
    o: { name: '水玉の国', color: '#e48aa6', desc: '点々（水玉）の模様ができます。' },
    '=': { name: 'しま・迷路の国', color: '#6c9fe0', desc: 'しまや迷路の模様ができます。' },
    '#': { name: '穴あきの国', color: '#4fb3a0', desc: 'ウサギの中に、草の穴が点々とあく模様ができます。' },
    L: { name: '動きつづける国', color: '#f0a33a', live: true, desc: '波やうずまきが、いつまでも動きつづけます。' },
  };

  const fRange = MAP ? [MAP.F0 - MAP.FS / 2, MAP.F0 + (MAP.nF - 0.5) * MAP.FS] : [0, 0.08];
  // 拡大表示：F 0.01〜0.06、k 0.045〜0.07（模様の帯のまわり）
  const ZOOM = MAP ? { fi0: Math.max(0, Math.round((0.01 - MAP.F0) / MAP.FS)), fi1: Math.min(MAP.nF - 1, Math.round((0.06 - MAP.F0) / MAP.FS)), ki0: Math.max(0, Math.round((0.045 - MAP.K0) / MAP.KS)), ki1: MAP.nK - 1 } : null;
  const kRange = MAP ? [MAP.K0 - MAP.KS / 2, MAP.K0 + (MAP.nK - 0.5) * MAP.KS] : [0.04, 0.07];

  let decoded = null;
  function decodeMap() {
    if (decoded) return decoded;
    const bin = atob(MAP.tiles), per = MAP.tile * MAP.tile;
    const tileOf = new Int32Array(MAP.cls.length).fill(-1);
    let t = 0;
    for (let i = 0; i < MAP.cls.length; i++) if (MAP.cls[i] !== '.' && MAP.cls[i] !== 'U') tileOf[i] = t++;
    const q = new Uint8Array(t * per);
    for (let j = 0; j < q.length; j++) { const b = bin.charCodeAt(j >> 1); q[j] = j & 1 ? b & 15 : b >> 4; }
    return (decoded = { tileOf, q, count: t });
  }
  function cellOf(F, k) {
    if (!MAP) return -1;
    const fi = Math.round((F - MAP.F0) / MAP.FS), ki = Math.round((k - MAP.K0) / MAP.KS);
    if (fi < 0 || ki < 0 || fi >= MAP.nF || ki >= MAP.nK) return -1;
    return fi * MAP.nK + ki;
  }
  const classAt = (F, k) => { const i = cellOf(F, k); return i < 0 ? null : MAP.cls[i]; };

  // ---- 再現チャレンジの判定（テストでも使う） ----
  const OBS_STEPS = 2000; // パラメータを変えてから、この コマ数 だけ動かしたら判定
  const ALIVE_V = 0.1; // ウサギの濃さの最大がこれより小さいと「全滅した」とみなす
  const inBox = (pt, F, k) => !!pt.box && F >= pt.box.fMin - 1e-9 && F <= pt.box.fMax + 1e-9 && k >= pt.box.kMin - 1e-9 && k <= pt.box.kMax + 1e-9;
  // st: { F, k, obs（変えてから動かしたコマ数）, maxV } → 合格した模様の id の配列
  function judge(pats, st) {
    if (st.obs < OBS_STEPS || !(st.maxV > ALIVE_V)) return [];
    return pats.filter((pt) => inBox(pt, st.F, st.k)).map((pt) => pt.id);
  }
  // 目標からのずれを、地図の向きで教える
  function advise(pt, F, k) {
    const b = pt.box, out = [];
    if (F < b.fMin) out.push('F をもう少し<b>大きく</b>（地図の<b>上</b>へ）');
    if (F > b.fMax) out.push('F をもう少し<b>小さく</b>（地図の<b>下</b>へ）');
    if (k < b.kMin) out.push('k をもう少し<b>大きく</b>（地図の<b>右</b>へ）');
    if (k > b.kMax) out.push('k をもう少し<b>小さく</b>（地図の<b>左</b>へ）');
    return out;
  }

  // 決まった乱数（左右の草原に同じ種をまくため）
  function seeded(a) {
    return function () {
      a |= 0; a = (a + 0x6d2b79f5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  // ウサギの群れ（v > th のかたまり）の数。端はパックマン型でつながる。
  function countGroups(sim, th = 0.2) {
    const { w, h: H, v } = sim, lab = new Uint8Array(sim.n), stack = [];
    let n = 0;
    for (let s = 0; s < sim.n; s++) {
      if (v[s] <= th || lab[s]) continue;
      n++; lab[s] = 1; stack.push(s);
      while (stack.length) {
        const i = stack.pop(), x = i % w, y = (i - x) / w;
        const nb = [y * w + (x + 1) % w, y * w + (x + w - 1) % w, ((y + 1) % H) * w + x, ((y + H - 1) % H) * w + x];
        for (const j of nb) if (v[j] > th && !lab[j]) { lab[j] = 1; stack.push(j); }
      }
    }
    return n;
  }

  // ================================================================
  // F-k マップ（クリックで F, k をえらぶ）
  //   opts: F, k, onPick(F, k), mode 'atlas'（見本）| 'country'（国の色分け）, palette,
  //         boxes: [{ box, label, state: 'done' | 'plain' }], places（true で全滅・一様の点に名前を出す）
  // ================================================================
  class FkMap {
    constructor(opts = {}) {
      this.o = Object.assign({ mode: 'atlas', palette: 'meadow', boxes: [], places: true, zoom: false }, opts);
      this.F = opts.F ?? 0.03; this.k = opts.k ?? 0.06;
      this.ML = 92; this.MR = 14; this.MT = 14; this.MB = 64;
      this.canvas = h('canvas', {
        role: 'img', 'aria-label': 'F-k マップ（模様の地図）。クリックした場所の F と k をえらべます',
        style: { display: 'block', width: '100%', height: 'auto', touchAction: 'manipulation', cursor: 'crosshair', borderRadius: '6px', border: '1px solid var(--line)', background: 'var(--card)' },
      });
      this.base = document.createElement('canvas');
      this.info = h('div', { class: 'readout', style: { textAlign: 'center' } });
      this.el = h('div', { style: { maxWidth: '560px', margin: '0 auto', width: '100%' } }, this.canvas, this.info);
      this._bind();
      this._layout();
    }
    // 表示するマスの範囲（zoom なら模様の帯のまわりだけ）
    _layout() {
      const w = this.o.zoom ? ZOOM : { fi0: 0, fi1: MAP.nF - 1, ki0: 0, ki1: MAP.nK - 1 };
      this.win = w;
      this.fr = [MAP.F0 + (w.fi0 - 0.5) * MAP.FS, MAP.F0 + (w.fi1 + 0.5) * MAP.FS];
      this.kr = [MAP.K0 + (w.ki0 - 0.5) * MAP.KS, MAP.K0 + (w.ki1 + 0.5) * MAP.KS];
      this.PW = (w.ki1 - w.ki0 + 1) * MAP.tile; this.PH = (w.fi1 - w.fi0 + 1) * MAP.tile;
      this.canvas.width = this.ML + this.PW + this.MR; this.canvas.height = this.MT + this.PH + this.MB;
      this.base.width = this.PW; this.base.height = this.PH;
      this._baseKey = '';
      this.draw();
    }
    xOf(k) { return this.ML + ((k - this.kr[0]) / (this.kr[1] - this.kr[0])) * this.PW; }
    yOf(F) { return this.MT + (1 - (F - this.fr[0]) / (this.fr[1] - this.fr[0])) * this.PH; }
    _at(ev) {
      const r = this.canvas.getBoundingClientRect();
      const x = ((ev.clientX - r.left) / r.width) * this.canvas.width, y = ((ev.clientY - r.top) / r.height) * this.canvas.height;
      const k = this.kr[0] + ((x - this.ML) / this.PW) * (this.kr[1] - this.kr[0]);
      const F = this.fr[0] + (1 - (y - this.MT) / this.PH) * (this.fr[1] - this.fr[0]);
      const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
      return { F: +clamp(F, Math.max(0.001, this.fr[0]), this.fr[1]).toFixed(4), k: +clamp(k, this.kr[0], this.kr[1]).toFixed(4) };
    }
    _bind() {
      let down = null, drag = false;
      this.canvas.addEventListener('pointerdown', (ev) => {
        down = { x: ev.clientX, y: ev.clientY };
        drag = ev.pointerType === 'mouse';
        if (drag) { this.canvas.setPointerCapture(ev.pointerId); const a = this._at(ev); this.set(a.F, a.k); }
      });
      this.canvas.addEventListener('pointermove', (ev) => { if (drag && down) { const a = this._at(ev); this.set(a.F, a.k); } });
      this.canvas.addEventListener('pointerup', (ev) => {
        if (!down) return;
        const moved = Math.hypot(ev.clientX - down.x, ev.clientY - down.y);
        if (drag || moved < 12) { const a = this._at(ev); this.set(a.F, a.k); this.o.onPick && this.o.onPick(a.F, a.k); }
        down = null; drag = false;
      });
      this.canvas.addEventListener('pointercancel', () => { down = null; drag = false; });
    }
    set(F, k) { this.F = F; this.k = k; this.draw(); }
    setMode(m) { this.o.mode = m; this.draw(); }
    setZoom(z) { this.o.zoom = !!z; this._layout(); }
    setPalette(name) { this.o.palette = name; this.draw(); }
    setBoxes(list) { this.o.boxes = list; this.draw(); }
    _buildBase() {
      const key = this.o.mode + ':' + this.o.palette;
      if (key === this._baseKey) return;
      this._baseKey = key;
      const { tileOf, q } = decodeMap();
      const TS = MAP.tile, per = TS * TS, W = this.PW, w = this.win;
      const img = this.base.getContext('2d').createImageData(this.PW, this.PH), d = img.data;
      const rgb = (css) => { const m = /(\d+)\D+(\d+)\D+(\d+)/.exec(css); return m ? [+m[1], +m[2], +m[3]] : [0, 0, 0]; };
      const hex = (s) => [parseInt(s.slice(1, 3), 16), parseInt(s.slice(3, 5), 16), parseInt(s.slice(5, 7), 16)];
      const lut = []; for (let i = 0; i < 16; i++) lut.push(rgb(RD.colorOf(this.o.palette, i / 15)));
      for (let fi = w.fi0; fi <= w.fi1; fi++) for (let ki = w.ki0; ki <= w.ki1; ki++) {
        const ci = fi * MAP.nK + ki, c = MAP.cls[ci], t = tileOf[ci];
        const x0 = (ki - w.ki0) * TS, y0 = (w.fi1 - fi) * TS;
        const flat = this.o.mode === 'country' ? hex(COUNTRIES[c].color) : lut[parseInt(MAP.lv[ci], 16)];
        for (let y = 0; y < TS; y++) for (let x = 0; x < TS; x++) {
          let col = flat;
          if (this.o.mode === 'atlas' && t >= 0) col = lut[q[t * per + y * TS + x]];
          else if (this.o.mode === 'country' && c === 'L' && ((x0 + x + y0 + y) % 10) < 3) col = [200, 120, 20];
          const o = ((y0 + y) * W + x0 + x) * 4;
          d[o] = col[0]; d[o + 1] = col[1]; d[o + 2] = col[2]; d[o + 3] = 255;
        }
      }
      this.base.getContext('2d').putImageData(img, 0, 0);
    }
    _centroid(c) {
      const w = this.win, key = c + JSON.stringify(w);
      this._cent = this._cent || {};
      if (key in this._cent) return this._cent[key];
      const nK = w.ki1 - w.ki0 + 1, nF = w.fi1 - w.fi0 + 1, seen = new Uint8Array(nK * nF);
      let best = null;
      for (let s0 = 0; s0 < seen.length; s0++) {
        if (seen[s0] || MAP.cls[(w.fi0 + Math.floor(s0 / nK)) * MAP.nK + w.ki0 + (s0 % nK)] !== c) continue;
        const stack = [s0], cells = []; seen[s0] = 1;
        while (stack.length) {
          const i = stack.pop(), x = i % nK, y = Math.floor(i / nK); cells.push([x, y]);
          for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
            const X = x + dx, Y = y + dy, j = Y * nK + X;
            if (X < 0 || Y < 0 || X >= nK || Y >= nF || seen[j]) continue;
            if (MAP.cls[(w.fi0 + Y) * MAP.nK + w.ki0 + X] !== c) continue;
            seen[j] = 1; stack.push(j);
          }
        }
        if (!best || cells.length > best.length) best = cells;
      }
      let res = null;
      if (best && best.length >= 6) {
        // かたまりの中で、まん中にいちばん近いマス
        const mx = best.reduce((a, p) => a + p[0], 0) / best.length, my = best.reduce((a, p) => a + p[1], 0) / best.length;
        const p = best.reduce((a, q) => ((q[0] - mx) ** 2 + (q[1] - my) ** 2 < (a[0] - mx) ** 2 + (a[1] - my) ** 2 ? q : a));
        res = [this.ML + (p[0] + 0.5) * MAP.tile, this.MT + this.PH - (p[1] + 0.5) * MAP.tile];
      }
      return (this._cent[key] = res);
    }
    _label(ctx, text, x, y, align = 'center', size = 22, color = '#1d1d1d') {
      ctx.font = `bold ${size}px sans-serif`; ctx.textAlign = align; ctx.textBaseline = 'middle';
      ctx.lineJoin = 'round'; ctx.lineWidth = 6; ctx.strokeStyle = 'rgba(255,255,255,0.92)';
      ctx.strokeText(text, x, y); ctx.fillStyle = color; ctx.fillText(text, x, y);
    }
    draw() {
      this._buildBase();
      const ctx = this.canvas.getContext('2d'), W = this.canvas.width, H = this.canvas.height;
      const ink = RD.ui.cssVar('--ink') || '#222', ink2 = RD.ui.cssVar('--ink-2') || '#555';
      const inside = (F, k) => F >= this.fr[0] && F <= this.fr[1] && k >= this.kr[0] && k <= this.kr[1];
      ctx.clearRect(0, 0, W, H);
      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(this.base, this.ML, this.MT);
      // 目盛り
      ctx.font = '20px sans-serif'; ctx.fillStyle = ink2; ctx.strokeStyle = ink2; ctx.lineWidth = 1.5;
      ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
      for (let i = 1; i <= 9; i++) {
        const F = i / 100;
        if (F < this.fr[0] || F > this.fr[1]) continue;
        const y = this.yOf(F);
        ctx.beginPath(); ctx.moveTo(this.ML - 6, y); ctx.lineTo(this.ML, y); ctx.stroke();
        ctx.fillText(F.toFixed(2), this.ML - 9, y);
      }
      ctx.textAlign = 'center'; ctx.textBaseline = 'top';
      for (let i = 6; i <= 15; i++) {
        const k = i * 0.005;
        if (k < this.kr[0] || k > this.kr[1]) continue;
        const x = this.xOf(k);
        ctx.beginPath(); ctx.moveTo(x, this.MT + this.PH); ctx.lineTo(x, this.MT + this.PH + 6); ctx.stroke();
        ctx.fillText(k.toFixed(3), x, this.MT + this.PH + 9);
      }
      ctx.fillStyle = ink; ctx.font = 'bold 21px sans-serif';
      ctx.fillText('k（ウサギの減りやすさ）→', this.ML + this.PW / 2, this.MT + this.PH + 36);
      ctx.save(); ctx.translate(18, this.MT + this.PH / 2); ctx.rotate(-Math.PI / 2);
      ctx.textBaseline = 'middle'; ctx.fillText('F（草の生えやすさ）→', 0, 0); ctx.restore();
      // 地名：全滅の国・ウサギだらけの国の、いちばん大きなかたまりのまん中に書く
      if (this.o.places) {
        for (const [c, text] of [['.', 'ウサギがいなくなる国'], ['U', 'ウサギだらけの国']]) {
          const pos = this._centroid(c);
          if (pos) this._label(ctx, text, Math.min(Math.max(pos[0], this.ML + 130), this.ML + this.PW - 130), pos[1], 'center', 22, '#333');
        }
      }
      // 模様の領域
      for (const b of this.o.boxes || []) {
        const x0 = this.xOf(b.box.kMin), x1 = this.xOf(b.box.kMax), y0 = this.yOf(b.box.fMax), y1 = this.yOf(b.box.fMin);
        if (x1 < this.ML || x0 > this.ML + this.PW || y1 < this.MT || y0 > this.MT + this.PH) continue;
        ctx.lineWidth = 5; ctx.strokeStyle = 'rgba(255,255,255,0.9)'; ctx.strokeRect(x0, y0, x1 - x0, y1 - y0);
        ctx.lineWidth = 2.5; ctx.strokeStyle = b.state === 'done' ? '#2c7a4b' : b.state === 'goal' ? '#e0303a' : '#222';
        if (b.state === 'goal') ctx.setLineDash([6, 4]);
        ctx.strokeRect(x0, y0, x1 - x0, y1 - y0);
        ctx.setLineDash([]);
        const right = x1 > this.ML + this.PW * 0.75;
        this._label(ctx, (b.state === 'done' ? '✓' : '') + b.label, right ? x0 - 6 : x1 + 6, (y0 + y1) / 2, right ? 'right' : 'left', 19,
          b.state === 'done' ? '#1f6a3c' : b.state === 'goal' ? '#b0202a' : '#1d1d1d');
      }
      // いまの場所
      if (inside(this.F, this.k)) {
        const x = this.xOf(this.k), y = this.yOf(this.F);
        ctx.strokeStyle = 'rgba(255,255,255,0.55)'; ctx.lineWidth = 1.5; ctx.setLineDash([6, 6]);
        ctx.beginPath(); ctx.moveTo(this.ML, y); ctx.lineTo(this.ML + this.PW, y); ctx.moveTo(x, this.MT); ctx.lineTo(x, this.MT + this.PH); ctx.stroke();
        ctx.setLineDash([]);
        ctx.lineWidth = 6; ctx.strokeStyle = '#fff'; ctx.beginPath(); ctx.arc(x, y, 13, 0, Math.PI * 2); ctx.stroke();
        ctx.lineWidth = 3; ctx.strokeStyle = '#e0303a'; ctx.beginPath(); ctx.arc(x, y, 13, 0, Math.PI * 2); ctx.stroke();
      }
      const c = classAt(this.F, this.k);
      this.info.innerHTML = `F = ${fmt(this.F, 4)}　k = ${fmt(this.k, 4)}` + (c ? `　→ <b>${COUNTRIES[c].name}</b>` : '　（地図の外）');
    }
  }
  if (MAP) RD.FkMap = FkMap;
  RD.fkMap = { MAP, COUNTRIES, classAt, fRange, kRange };
  RD.ch7 = { OBS_STEPS, ALIVE_V, inBox, judge, advise, classAt, decodeMap, countGroups, seeded, MAP };

  // ================================================================
  // 章の本体
  // ================================================================
  const STYLE = `
.ch7-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.ch7-pair .lbl { font-size: 0.85rem; text-align: center; color: var(--ink-2); margin-bottom: 4px; line-height: 1.4; }
.ch7-pair .cnt { font-family: var(--font-mono); font-size: 0.85rem; text-align: center; color: var(--ink-2); min-height: 1.4em; }
.ch7-hide { position: relative; }
.ch7-hide.covered canvas { filter: blur(6px) grayscale(1); opacity: 0.35; }
.ch7-hide.covered::after { content: "？"; position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 2.6rem; color: var(--ink-2); pointer-events: none; }
.ch7-analogy { display: grid; gap: 10px; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); margin: 12px 0; }
.ch7-analogy .card { margin: 0; }
.ch7-analogy .card + .card { margin-top: 0; }
.ch7-analogy .big { font-size: 1.6rem; }
.ch7-story { counter-reset: st; list-style: none; padding: 0; margin: 10px 0; }
.ch7-story li { position: relative; padding: 4px 0 4px 2.2em; margin: 4px 0; }
.ch7-story li::before { counter-increment: st; content: counter(st); position: absolute; left: 0; top: 4px; width: 1.6em; height: 1.6em; border-radius: 50%; background: var(--accent); color: var(--accent-ink); font-weight: 700; display: flex; align-items: center; justify-content: center; font-size: 0.9rem; }
.ch7-key { font-size: 1.15rem; font-weight: 700; text-align: center; margin: 8px 0; }
.ch7-graph canvas { display: block; width: 100%; height: auto; border: 1px solid var(--line); border-radius: 6px; background: var(--card); }
.ch7-meter { height: 12px; border-radius: 6px; background: linear-gradient(90deg, #4fb3a0, #f0e08a, #f0a33a); position: relative; border: 1px solid var(--line); }
.ch7-meter i { position: absolute; top: -4px; width: 4px; height: 18px; background: var(--ink); border-radius: 2px; transform: translateX(-2px); }
.ch7-meter-lbl { display: flex; justify-content: space-between; font-size: 0.8rem; color: var(--ink-2); }
.ch7-legend { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 0.82rem; justify-content: center; margin-top: 4px; }
.ch7-legend span { display: inline-flex; align-items: center; gap: 4px; }
.ch7-legend b { display: inline-block; width: 14px; height: 14px; border-radius: 3px; border: 1px solid rgba(0,0,0,.25); }
.ch7-prog { height: 10px; border-radius: 5px; background: var(--card-2); border: 1px solid var(--line); overflow: hidden; }
.ch7-prog > div { height: 100%; width: 0; background: var(--accent); }
.ch7-prog.done > div { background: var(--ok); }
.ch7-status { font-size: 0.92rem; min-height: 1.5em; margin-top: 6px; }
.ch7-target { display: grid; grid-template-columns: 96px 1fr; gap: 12px; align-items: center; }
.ch7-target img, .ch7-target .ph { width: 96px; height: 96px; border-radius: 6px; border: 1px solid var(--line); display: block; image-rendering: auto; background: var(--card-2); }
.ch7-target .ph { display: flex; align-items: center; justify-content: center; font-size: 0.75rem; color: var(--ink-3); text-align: center; }
.ch7-kind { display: inline-block; font-size: 0.78rem; border-radius: 999px; padding: 0 8px; border: 1px solid var(--line); margin-left: 4px; }
.ch7-kind.live { border-color: #f0a33a; color: #b06a00; }
.ch7-kind.still { border-color: #4fb3a0; color: #1f7a66; }
.ch7-ctrl { display: grid; gap: 8px; margin-top: 10px; }
@media (max-width: 959px) { .ch7-rep .step-demo { order: -1; } }
.ch7-rep { margin-top: 0; }
.ch7-rep .quiz:first-child { margin-top: 0; }
.ch7-bar { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
`;

  // 再現チャレンジの目標の説明（見た目の言葉だけ。数は patterns.js から読む）
  const DESC = {
    mitosis: '増えながら分かれていく点。1つの点が2つに分かれて、数を増やしていきます。',
    spots: 'まるい点が、すき間をあけて並んだ模様。',
    maze: '線がくねくねとつながった、迷路のような模様。',
    coral: 'まん中から枝分かれしながら広がる、サンゴのようなしま。',
    holes: 'ウサギの中に、草の「穴」が点々とあいた模様。',
    spiral: '三日月形の波が動きまわり、はしがくるっと巻く模様。止まりません。',
  };

  // Runner は再生バーが画面に見えているときだけ動く。再生バーが草原から離れているレイアウトでは、
  // 見張る要素を草原を含むカードに変える。
  const reduceMotion = () => !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
  function watch(runner, el) { runner.watch(el); }

  // つまみ＋数の入力欄。onInput は値が変わるたび、input の 'change'（指をはなした・入力を確定した）で onCommit。
  function numSlider({ label, min, max, step: st, value, digits = 4, onInput, onCommit }) {
    const s = RD.ui.slider({ label, min, max, step: st, value, format: (v) => fmt(v, digits), onInput: (v) => { txt.value = fmt(v, digits); onInput && onInput(v); } });
    s.el.querySelector('output').hidden = true;
    const txt = h('input', { type: 'text', inputmode: 'decimal', autocomplete: 'off', value: fmt(value, digits), 'aria-label': label.replace(/<[^>]+>/g, '') + ' の値',
      style: { width: '5.6em', padding: '4px 6px', border: '1.5px solid var(--line)', borderRadius: '8px', background: 'var(--card)', fontFamily: 'var(--font-mono)', fontSize: '0.9rem' } });
    const apply = () => {
      const v = RD.ui.parseNum(txt.value);
      if (!isFinite(v) || v < min || v > max) { txt.style.borderColor = 'var(--ng)'; return; }
      txt.style.borderColor = '';
      s.set(v); txt.value = fmt(v, digits);
      onInput && onInput(v); onCommit && onCommit(v);
    };
    txt.addEventListener('change', apply);
    txt.addEventListener('keydown', (e) => { if (e.key === 'Enter') apply(); });
    s.input.addEventListener('change', () => onCommit && onCommit(+s.input.value));
    const el = h('div', { style: { display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', gap: '8px', alignItems: 'center' } }, s.el, txt);
    return { el, input: s.input, set(v) { s.set(v); if (document.activeElement !== txt) txt.value = fmt(v, digits); }, get value() { return s.value; } };
  }

  RD.registerChapter({
    id: 'ch7',
    no: 7,
    title: '模様ができる理由と、模様の地図',
    desc: '「広がると平らになる」はずなのに、なぜ模様？ 謎を解いて、模様の地図で狙った模様を出します。',
    goal: '模様ができる理由を説明できる。F-k マップ（模様の地図）を使って、狙った模様を出せる。',
    required: 8, // 問題1〜5（理由・予想3つ・分類） ＋ 再現チャレンジ6つのうち3つ
    isCleared: (solved) => ['why', 'same-d', 'small-d', 'seed', 'kind'].every((id) => solved.includes(id))
      && solved.filter((id) => id.startsWith('rep-')).length >= 3,

    render(root, ctx) {
      root.appendChild(h('style', { text: STYLE }));
      const pats = RD.patterns || [];
      const P = (id) => pats.find((x) => x.id === id);
      const D = RD.SIM_DEFAULTS || {};
      const Du0 = D.Du ?? 1.0, Dv0 = D.Dv ?? 0.5;
      if (!P('spots') || !P('maze') || !MAP) {
        root.appendChild(note('<p>模様のデータ（patterns.js）が読み込まれていないため、この章のデモを表示できません。</p>', 'warn'));
        return;
      }
      const sims = [];
      const newSim = (N, pt, extra) => { const s = new RD.Sim(Object.assign({ w: N, h: N, F: pt.F, k: pt.k }, extra)); sims.push(s); return s; };
      const pairSim = (a, b) => ({ a, b, step(n) { a.step(n); b.step(n); return this; }, get steps() { return a.steps; }, get exploded() { return a.exploded || b.exploded; } });

      // ---------------- 1. 謎をふりかえる ----------------
      root.appendChild(step({
        title: 'いよいよ謎解きです',
        text: [
          p('ここまでで、ゴールの式をぜんぶ読めるようになりました。いよいよ、ずっと残してきた<b>大きな謎</b>を解きます。'),
          note(`<p><b>第4章でわかったこと：</b>拡散（広がること）は、でこぼこを<b>ならして平らにする</b>働きです。インクを落としても、最後は一様（どこも同じ）になりました。</p>
            <p><b>第6章で見たこと：</b>ところが、草とウサギの式を全部オンにすると、平らになるどころか<b>模様が生まれました</b>。</p>
            <p>🔍 <b>謎：</b>平らにする働きがあるのに、なぜ模様ができるの？ しかも水玉や迷路の<b>間隔がそろっている</b>のはなぜ？</p>`, 'mystery'),
          p('この章の前半でこの謎を解き、後半では「模様の地図」を使って、<b>自分の狙った模様を出せる</b>ようになります。'),
        ],
      }));

      // ---------------- 2. 3つのたとえ ----------------
      root.appendChild(step({
        title: '身近なたとえ：近くは仲間、遠くはじゃま',
        text: [
          p('まず、模様とよく似たことが起きている身近な例を3つ見てみましょう。'),
          h('div', { class: 'ch7-analogy' },
            card(null, h('div', { class: 'big', text: '🚃' }), h('p', { html: '<b>電車の座席</b><br>知らない人どうしは、1つ空けて座りますね。座りたい（増えたい）けれど、<b>すぐ隣はいや</b>。だから、座る人は<b>だいたい同じ間隔</b>に並びます。' })),
            card(null, h('div', { class: 'big', text: '🌳' }), h('p', { html: '<b>乾いた土地の木</b><br>雨の少ない土地では、木が根元のまわりの水を<b>ひとりじめ</b>します。すぐ近くには別の木が育たないので、木は<b>点々と、同じくらいの間隔</b>で並びます。（本当にある景色です）' })),
            card(null, h('div', { class: 'big', text: '🔥🚁' }), h('p', { html: '<b>火事と消防士</b><br>森に火がつくと、ゆっくり燃え広がります。消防士はヘリコプターで<b>火より速く</b>先回りして、まわりを守ります。すると、焼けあとは<b>点々</b>になります。' }))),
          note('<p class="ch7-key">近くは仲間を増やし、遠くはじゃまをする</p><p>この2つがそろうと、「かたまり」が<b>一定の間隔</b>で並びます。そして、火事の例のように、<b>じゃまをする側のほうが速く広がる</b>ことがカギです。</p>'),
          p('では、草とウサギの草原では、だれが「仲間」で、だれが「じゃま」なのでしょう？'),
        ],
      }));

      // ---------------- 3. 草原で何が起きているか ----------------
      const spots = P('spots');
      const sSim = newSim(96, spots);
      sSim.seed('center');
      let row = sSim.h >> 1, autoRow = true, frameNo = 0;
      const sView = new RD.FieldView(sSim, { maxPx: 384, readout: false, onPick: (i) => { row = sSim.xy(i)[1]; autoRow = false; sView.picked = null; drawStory(); } });
      const graph = h('canvas', { width: 640, height: 230 });
      const fieldSeg = RD.ui.segmented([{ value: 'v', label: '🐇 ウサギ v' }, { value: 'u', label: '🌱 草 u' }], 'v', (f) => { sView.setField(f, f === 'u' ? [0, 1] : [0, 0.4]); sView.setPalette(f === 'u' ? 'grass' : 'meadow'); drawStory(); });
      function drawStory() {
        // 草原をクリックするまでは、いちばんウサギの濃いマスを通る行を自動でえらぶ
        if (autoRow && frameNo++ % 30 === 0) { let mi = 0; for (let i = 1; i < sSim.n; i++) if (sSim.v[i] > sSim.v[mi]) mi = i; row = sSim.xy(mi)[1]; }
        sView.render();
        // 断面の線
        const c = sView.canvas.getContext('2d'), cs = sView.cell, yy = row * cs + cs / 2;
        c.strokeStyle = 'rgba(255,255,255,0.85)'; c.lineWidth = 2; c.setLineDash([8, 6]);
        c.beginPath(); c.moveTo(0, yy); c.lineTo(sView.canvas.width, yy); c.stroke(); c.setLineDash([]);
        // 断面グラフ
        const g = graph.getContext('2d'), W = graph.width, H = graph.height, pad = { l: 44, r: 10, t: 14, b: 26 };
        g.clearRect(0, 0, W, H);
        const ink2 = RD.ui.cssVar('--ink-2'), line = RD.ui.cssVar('--line');
        const Y = (val) => H - pad.b - val * (H - pad.t - pad.b);
        g.font = '14px sans-serif'; g.fillStyle = ink2; g.textAlign = 'right'; g.strokeStyle = line; g.lineWidth = 1;
        for (const t of [0, 0.5, 1]) { g.beginPath(); g.moveTo(pad.l, Y(t)); g.lineTo(W - pad.r, Y(t)); g.stroke(); g.fillText(String(t), pad.l - 6, Y(t) + 5); }
        g.textAlign = 'left'; g.fillText('点線の上の草とウサギ（左はし → 右はし）', pad.l + 4, H - 6);
        const X = (x) => pad.l + (x / (sSim.w - 1)) * (W - pad.l - pad.r);
        const series = [[sSim.u, RD.ui.cssVar('--t-u') || '#3a8a35', 1], [sSim.v, RD.ui.cssVar('--t-v') || '#9a5a2a', 1]];
        for (const [a, col, scale] of series) {
          g.strokeStyle = col; g.lineWidth = 3; g.beginPath();
          for (let x = 0; x < sSim.w; x++) { const val = Math.min(1, a[row * sSim.w + x] * scale); x ? g.lineTo(X(x), Y(val)) : g.moveTo(X(x), Y(val)); }
          g.stroke();
        }
      }
      const sRunner = new RD.Runner({
        sim: sSim, onFrame: drawStory, speeds: [{ label: 'ゆっくり', spf: 2 }, { label: 'ふつう', spf: 6 }, { label: 'はやい', spf: 16 }], speed: 1,
        onReset: () => { sSim.seed('center'); row = sSim.h >> 1; autoRow = true; },
      });
      root.appendChild(step({
        title: '草原で起きていること',
        text: [
          p('デモの草原では、まん中にウサギの群れを1つだけ放しました。▶ 再生して、何が起きるか見てください。グラフは、点線の上の<b class="t-u">草</b>と<b class="t-v">ウサギ</b>の量です。点線は、ウサギがいちばん濃い場所を自動で通ります（草原をクリックすると、点線の場所を自分で決められます）。'),
          h('ol', { class: 'ch7-story' },
            h('li', { html: '<b>近くは仲間を増やす：</b>ウサギはペアで出会うと増えます（<span class="t-react">uv²</span>）。群れの中は出会いが多いので、群れはどんどん育ちます。' }),
            h('li', { html: '<b>草を食べつくす：</b>育った群れは、その場所の草を食べつくします。グラフで、ウサギの山のところだけ草がへこんでいます。' }),
            h('li', { html: '<b>草が流れこむ：</b>草はウサギより<b>速く広がる</b>（<i>D<sub>u</sub></i> が大きい）ので、まわりから草が流れこみます。その分、<b>少しはなれた場所の草まで薄く</b>なります。グラフで、<b class="t-u">草の谷</b>のすそは、<b class="t-v">ウサギの山</b>のすそより外側まで広がっていますね。' }),
            h('li', { html: '<b>遠くはじゃまをする：</b>草が薄い場所では、ウサギは増えられません。だから<b>すぐ隣には新しい群れが育たず</b>、草がたっぷり残っている<b>少しはなれた場所</b>に次の群れができます。' })),
          note('<p>こうして、群れと群れのあいだに<b>一定の間隔</b>があきます。草とウサギの草原では、じゃまの正体は<b>エサ（草）の取り合い</b>だったのです。</p>', 'story'),
          more('「草のへこみのほうが広い」を数字でたしかめると',
            '<p>このドリルのシミュレーションで、1つだけの点を横に切ってみました（分裂する点の F, k、草原 96×96、種はまん中に1つ）。ウサギが山の高さの1割以上いる幅は約 15 マス、草が谷の深さの1割以上へこんでいる幅は約 19 マスでした。草のへこみは、ウサギのいる場所より<b>外側まで</b>広がっています。</p>'),
        ],
        demo: [card(null, h('div', { class: 'row', style: { justifyContent: 'center', marginBottom: '8px' } }, fieldSeg.el), sView.el, h('div', { class: 'ch7-graph', style: { marginTop: '8px' } }, graph), h('div', { class: 'graph-legend' }, h('span', { class: 't-u', html: '🌱 草 <i>u</i>' }), h('span', { class: 't-v', html: '🐇 ウサギ <i>v</i>' })), sRunner.el)],
      }));

      root.appendChild(ctx.quiz({
        id: 'why',
        type: 'choice',
        q: '<p>ウサギの群れと群れのあいだに、<b>間隔があく</b>のはなぜでしょう？</p>',
        options: [
          { text: '拡散は、でこぼこを平らにする働きだから', why: '<p>拡散が1種類だけなら、たしかに平らになります（第4章）。でもそれでは模様は<b>消える</b>はずですね。ここでは「草が速く流れこむ」ことが、逆に間隔を作っています。</p>' },
          { text: '最初に種をまいた場所が、たまたま同じ間隔だったから', why: '<p>デモでは、種はまん中に<b>1つだけ</b>でした。それでも群れが分かれて、間隔をあけて並びましたね。間隔は種の場所では決まりません。</p>' },
          { text: '群れが草を食べつくし、まわりから草が流れこむので、少しはなれた場所まで草が薄くなり、すぐ隣には群れが育たないから', correct: true },
          { text: 'ウサギは、ほかの群れのウサギがきらいで、はなれようとするから', why: '<p>式の中に「ほかの群れをきらう」ルールはありません。ウサギはただ、草を食べてペアで増えるだけです。じゃまをしているのは<b>草（エサ）の取り合い</b>です。</p>' },
        ],
        hints: ['群れのまわりの「草」がどうなっているかに注目しましょう。', 'グラフで、草の谷のすそとウサギの山のすそ、どちらが外側まで広がっていましたか？', '草が薄い場所では、ウサギは増えられません。では、すぐ隣はどうなるでしょう？'],
        explain: '<p>「近くは仲間を増やし（ペアで増える）、遠くはじゃまをする（草の取り合い）」。これが間隔の正体です。</p>',
      }));

      // ---------------- 4. 実験1：Du = Dv ----------------
      const maze = P('maze');
      const mkPair = (pt, la, lb, seedStyle, opA, opB, seedNo) => {
        const a = newSim(80, pt, opA), b = newSim(80, pt, opB);
        const reseed = () => { a.seed(seedStyle, seeded(seedNo)); b.seed(seedStyle, seeded(seedNo)); };
        reseed();
        const va = new RD.FieldView(a, { maxPx: 240, readout: false, colorbar: false }), vb = new RD.FieldView(b, { maxPx: 240, readout: false, colorbar: false });
        const ca = h('div', { class: 'cnt' }), cb = h('div', { class: 'cnt' });
        const wrapB = h('div', { class: 'ch7-hide covered' }, vb.el);
        const el = h('div', { class: 'ch7-pair' }, h('div', null, h('div', { class: 'lbl', html: la }), va.el, ca), h('div', null, h('div', { class: 'lbl', html: lb }), wrapB, cb));
        return { a, b, va, vb, ca, cb, el, reseed, uncover: () => wrapB.classList.remove('covered') };
      };
      const ex1 = mkPair(maze, `いつもの草原<br><i>D<sub>u</sub></i> = ${fmt(Du0)}, <i>D<sub>v</sub></i> = ${fmt(Dv0)}`, `ウサギも速い草原<br><i>D<sub>u</sub></i> = <i>D<sub>v</sub></i> = ${fmt(Du0)}`, 'random', {}, { Dv: Du0 }, 3);
      const ex1Runner = new RD.Runner({
        sim: pairSim(ex1.a, ex1.b), onFrame: () => { ex1.va.render(); ex1.vb.render(); }, speeds: [{ label: 'ふつう', spf: 8 }, { label: 'はやい', spf: 24 }], speed: 1,
        onReset: () => ex1.reseed(),
      });
      ex1Runner.setEnabled(false);
      root.appendChild(step({
        title: '実験1：ウサギも草と同じ速さで広がったら？',
        text: [
          p('たとえの「火事と消防士」では、消防士のほうが<b>速い</b>ことがカギでした。草とウサギでは、速く広がるのは草（<i>D<sub>u</sub></i> = ' + fmt(Du0) + '）、ゆっくりなのはウサギ（<i>D<sub>v</sub></i> = ' + fmt(Dv0) + '）です。'),
          p(`では、ウサギも草と<b>同じ速さ</b>（<i>D<sub>v</sub></i> = <i>D<sub>u</sub></i> = ${fmt(Du0)}）で広がるようにしたら、どうなるでしょう？ デモの2つの草原には、<b>同じ場所に同じ種</b>がまいてあります。F と k は「迷路」の値です。`),
          note('<p>まず次の問題で予想してから、動かしてたしかめましょう（予想するまで「ウサギも速い草原」は「？」になっています）。</p>'),
        ],
        demo: [card(null, ex1.el, h('div', { style: { height: '8px' } }), ex1Runner.el)],
      }));
      root.appendChild(ctx.quiz({
        id: 'same-d',
        type: 'predict',
        q: '<p>ウサギも草と同じ速さで広がる（<i>D<sub>u</sub></i> = <i>D<sub>v</sub></i>）と、模様はどうなるでしょう？</p>',
        options: [
          { text: '変わらない。広がる速さは模様に関係ない', why: '<p>広がる速さの<b>ちがい</b>こそが大事でした。速さがそろうと、「遠くはじゃまをする」が働かなくなります。</p>' },
          { text: '迷路がもっとくっきりする', why: '<p>反対でした。ウサギが速く散らばると、群れがまとまれなくなります。</p>' },
          { text: '模様ができない。ウサギがいなくなって、どこも同じ（草だけ）の草原になる', correct: true },
          { text: '迷路の間隔が広くなる', why: '<p>間隔が変わるのは、<b>両方の速さを同じ割合で</b>変えたときです（次の実験）。速さをそろえると、模様そのものができなくなります。</p>' },
        ],
        observe: () => { ex1.uncover(); ex1Runner.setEnabled(true); ex1Runner.play(); },
        explain: `<p>「ウサギも速い草原」では、ウサギが草と同じ速さで散らばるので、群れが<b>まとまれません</b>。ウサギはペアで出会わないと増えられない（<span class="t-react">uv²</span>）ので、薄く散らばったウサギは増えられず、数百コマのうちにいなくなります。残るのは、どこも同じ<b>草だけの草原</b>です。模様はできません。</p>
          <p>模様ができるには、<b>草（じゃまをする側）がウサギより速く広がる</b>ことが必要なのです。</p>`,
      }));
      root.appendChild(more('もっと詳しく：どのくらい速さがちがえばいい？',
        `<p>このドリルのシミュレーションで、迷路の F, k のまま <i>D<sub>v</sub></i> を少しずつ <i>D<sub>u</sub></i> に近づけてみました（<i>D<sub>u</sub></i> = 1）。<i>D<sub>v</sub></i> が <i>D<sub>u</sub></i> の<b>7割</b>までは迷路ができましたが、<b>9割</b>では消えてしまいました。</p>
         <p>水玉、迷路、サンゴ、穴あき、うずまきのどの値でも、<i>D<sub>u</sub></i> = <i>D<sub>v</sub></i> にすると、ウサギはいなくなりました。地図の「ウサギだらけの国」に近い値では、反対にウサギが一面に広がって<b>一色</b>になることもあります。どちらにしても、模様はできません。チューリングが1952年に見つけたのも、「<b>2つの物質の広がる速さがちがう</b>と、一様な状態がこわれて模様ができる」ということでした。</p>`));

      // ---------------- 5. 実験2：D を両方小さく ----------------
      const ex2 = mkPair(spots, `いつもの草原<br><i>D<sub>u</sub></i> = ${fmt(Du0)}, <i>D<sub>v</sub></i> = ${fmt(Dv0)}`, `両方とも半分<br><i>D<sub>u</sub></i> = ${fmt(Du0 / 2)}, <i>D<sub>v</sub></i> = ${fmt(Dv0 / 2)}`, 'noise', {}, { Du: Du0 / 2, Dv: Dv0 / 2 }, 5);
      let ex2Frames = 0;
      const ex2Count = () => { ex2.ca.textContent = `群れの数：${countGroups(ex2.a)}`; if (!ex2.cb.parentNode.querySelector('.covered')) ex2.cb.textContent = `群れの数：${countGroups(ex2.b)}`; };
      const ex2Runner = new RD.Runner({
        sim: pairSim(ex2.a, ex2.b), onFrame: () => { ex2.va.render(); ex2.vb.render(); if (ex2Frames++ % 20 === 0) ex2Count(); }, speeds: [{ label: 'ふつう', spf: 8 }, { label: 'はやい', spf: 24 }], speed: 1,
        onReset: () => { ex2.reseed(); ex2Count(); },
      });
      ex2Runner.setEnabled(false);
      root.appendChild(step({
        title: '実験2：両方ともゆっくり広がったら？',
        text: [
          p('今度は、速さの<b>比</b>（草はウサギの2倍速い）はそのままにして、草もウサギも<b>両方とも半分</b>の速さにしてみます。F と k は「水玉」の値です。'),
          p('「遠くはじゃまをする」の「遠く」が、どう変わりそうか考えてみましょう。'),
        ],
        demo: [card(null, ex2.el, h('div', { style: { height: '8px' } }), ex2Runner.el)],
      }));
      root.appendChild(ctx.quiz({
        id: 'small-d',
        type: 'predict',
        q: '<p>草もウサギも、広がる速さ（<i>D<sub>u</sub></i> と <i>D<sub>v</sub></i>）を両方とも半分にすると、水玉はどうなるでしょう？</p>',
        options: [
          { text: '水玉が大きくなり、まばらになる', why: '<p>反対でした。草が流れこんでくる距離が<b>短く</b>なるので、じゃまが届く範囲もせまくなります。</p>' },
          { text: '水玉が小さく、細かく（ぎっしり）なる', correct: true },
          { text: '模様が消える', why: '<p>模様が消えるのは、速さが<b>そろった</b>ときでした。ここでは草はまだウサギの2倍速いので、模様はできます。</p>' },
          { text: '何も変わらない', why: '<p>F と k が同じなので模様の<b>種類</b>（水玉）は同じですが、<b>大きさ</b>は変わります。</p>' },
        ],
        observe: () => { ex2.uncover(); ex2Runner.setEnabled(true); ex2Runner.play(); ex2Count(); },
        explain: `<p>広がる速さが半分になると、草が流れこんでくる距離、つまり<b>じゃまが届く距離</b>が短くなります。だから群れどうしの間隔もせまくなり、水玉は小さく、数は多くなります。</p>
          <p>このドリルのシミュレーションでは、両方を半分にすると、間隔はおよそ <b>0.7 倍</b>、水玉の数はおよそ <b>2 倍</b>になりました。そのかわり、広がるのもゆっくりになるので、草原がうまるまでに時間がかかります。</p>`,
      }));
      root.appendChild(note(`<p><b>🔍 謎の答え</b></p>
        <p>拡散は、<b>1種類だけ</b>なら、でこぼこをならして平らにします。でも、<b>草とウサギの2種類</b>が、<b>ちがう速さ</b>で広がりながら食べたり増えたりすると、拡散が逆に<b>模様を作る</b>のです。</p>
        <ul><li>近くは仲間を増やす（ペアで増える）</li><li>遠くはじゃまをする（速く広がる草の取り合い）</li><li>じゃまの届く距離（広がる速さ）が、模様の間隔を決める</li></ul>`, 'mystery'));

      // ---------------- 6. 模様の地図 ----------------
      const exStart = P('spots');
      const mSim = newSim(128, exStart);
      let mSeed = 'random';
      mSim.seed(mSeed);
      const mView = new RD.FieldView(mSim, { maxPx: 384 });
      let reseedOnPick = true;
      const mMap = new FkMap({ F: exStart.F, k: exStart.k, onPick: (F, k) => { mSim.setParams({ F, k }); if (reseedOnPick) mSim.seed(mSeed); mView.render(); } });
      const legend = h('div', { class: 'ch7-legend' }, Object.values(COUNTRIES).map((c) => h('span', null, h('b', { style: { background: c.color } }), c.name)));
      legend.hidden = true;
      const modeSeg = RD.ui.segmented([{ value: 'atlas', label: '模様の見本' }, { value: 'country', label: '国の色分け' }], 'atlas', (m) => { mMap.setMode(m); legend.hidden = m !== 'country'; });
      const mRunner = new RD.Runner({ sim: mSim, onFrame: () => mView.render(), speeds: [{ label: 'ふつう', spf: 6 }, { label: 'はやい', spf: 16 }, { label: 'とても速い', spf: 36 }], speed: 1, autoplay: true, onReset: () => mSim.seed(mSeed) });
      const reseedTg = RD.ui.toggle('地図をクリックしたら、種をまき直す', true, (v) => { reseedOnPick = v; });
      const mapCard = card(null, mView.el, mRunner.el, h('div', { class: 'row', style: { justifyContent: 'center', marginTop: '8px' } }, reseedTg.el));
      watch(mRunner, mapCard);
      const zoomSeg = RD.ui.segmented([{ value: 'all', label: '全体' }, { value: 'zoom', label: '模様の帯を拡大' }], 'all', (z) => mMap.setZoom(z === 'zoom'));
      root.appendChild(step({
        title: '模様の地図（F-k マップ）',
        text: [
          p('模様の種類は、<b>F（草の生えやすさ）</b>と<b>k（ウサギの減りやすさ）</b>の2つの数で決まります。そこで、横に k、縦に F をとって、それぞれの場所でどんな模様ができるかを並べた<b>地図</b>を作りました。'),
          p('地図の小さな四角1つ1つが、その F, k で草原を動かしたときの<b>見本</b>です。地図をクリック（タップ）すると、その場所の F, k で草原が動きます。'),
          note(`<p><b>国の地図</b>として見てみましょう。</p>
            <ul><li>左上には広い「<b>ウサギだらけの国</b>」（一面ウサギで、模様なし）</li>
            <li>右と下には広い「<b>ウサギがいなくなる国</b>」（草だけ）</li>
            <li>そのあいだの<b>細い帯</b>に、水玉、しま・迷路、穴あき、動きつづける模様などの<b>小さな国々</b>がひしめいています</li></ul>`, 'story'),
          p('<b>国境</b>の近くでは、F や k が 0.002 ずれただけで、となりの国（別の模様）になることがあります。F = 0.04 のような小さな数のちがいが大事なのは、このためです。いろいろな国を旅してみましょう。'),
          more('この地図はどうやって作ったの？',
            '<p>このドリルと同じ計算（Du = 1、Dv = 0.5、dt = 0.8）で、F を 0.0025 きざみ、k を 0.001 きざみに変えながら、64×64 マスの草原を 12000 コマずつ動かしました。全部で 899 回のシミュレーションです。種のまき方や草原の大きさによって、国境の場所は少しずれることがあります。</p>' +
            '<p>この地図は、1993年にピアソンという研究者が Gray-Scott モデルの模様を分類した地図をもとにした考え方です。</p>'),
        ],
        demo: [card(null, h('div', { class: 'row', style: { justifyContent: 'center', marginBottom: '8px' } }, modeSeg.el, zoomSeg.el), mMap.el, legend),
          mapCard],
      }));

      // ---------------- 7. 種を変えても同じ国（T17） ----------------
      const ex3 = mkPair(maze, '種：まん中に1つ', '種：あちこちに数か所', 'center', {}, {}, 9);
      ex3.b.seed('random', seeded(9));
      ex3.reseed = () => { ex3.a.seed('center'); ex3.b.seed('random', seeded(9)); };
      const ex3Runner = new RD.Runner({ sim: pairSim(ex3.a, ex3.b), onFrame: () => { ex3.va.render(); ex3.vb.render(); }, speeds: [{ label: 'ふつう', spf: 8 }, { label: 'はやい', spf: 24 }], speed: 1, onReset: () => ex3.reseed() });
      ex3Runner.setEnabled(false);
      root.appendChild(step({
        title: '種を変えたら、模様の種類も変わる？',
        text: [
          p('デモの2つの草原は、F と k がまったく同じ（迷路の国）です。ちがうのは、<b>最初にウサギを放す場所（種）</b>だけ。「まん中に1つ」と「あちこちに数か所」です。'),
        ],
        demo: [card(null, ex3.el, h('div', { style: { height: '8px' } }), ex3Runner.el)],
      }));
      root.appendChild(ctx.quiz({
        id: 'seed',
        type: 'predict',
        q: '<p>F と k が同じで、種のまき方だけがちがうと、できる模様はどうなるでしょう？</p>',
        options: [
          { text: '種の形によって、水玉になったり迷路になったりする', why: '<p>模様の<b>種類</b>は、F と k（地図のどの国にいるか）で決まります。種が決めるのは、模様が<b>どこから</b>育つかや、細かい形です。</p>' },
          { text: 'どちらも同じ種類の模様（迷路）になる。ただし、線の場所や曲がり方はちがう', correct: true },
          { text: '種が1つのほうは、模様も1つの群れしかできない', why: '<p>群れは草を取り合いながら、となりに次の群れを作って広がっていきます。種が1つでも、草原いっぱいに模様が広がります。</p>' },
        ],
        observe: () => { ex3.uncover(); ex3Runner.setEnabled(true); ex3Runner.play(); },
        explain: `<p><b>模様の種類は F と k で決まり、模様の場所や細かい形は種で決まる</b>のです。シマウマどうしでも、しまの1本1本の形は1頭ずつちがうのと同じですね。</p>
          <p>ただし、国境ぎりぎりの場所や、うずまきのような「動きつづける模様」では、種のまき方で出かたが変わることもあります。</p>`,
      }));

      // ---------------- 8. 完成する模様と、生きている模様（T18） ----------------
      const kSim = newSim(80, pats[0]);
      const kView = new RD.FieldView(kSim, { maxPx: 320, readout: false, colorbar: false });
      const meterI = h('i', { style: { left: '0%' } });
      const meterTxt = h('div', { class: 'readout' });
      let kPrev = null, kAcc = 0, kCur = pats[0];
      const kLoad = (pt) => { kCur = pt; kSim.setParams({ F: pt.F, k: pt.k }); kSim.seed(pt.seed || 'random', seeded(21)); kPrev = kSim.v.slice(); kAcc = 0; meterTxt.textContent = '動き具合を測っています…'; kView.render(); };
      const kSeg = RD.ui.segmented(pats.map((pt) => ({ value: pt.id, label: pt.name })), pats[0].id, (id) => kLoad(P(id)));
      const kRunner = new RD.Runner({
        sim: kSim, onFrame: () => kView.render(), speeds: [{ label: 'ふつう', spf: 10 }, { label: 'はやい', spf: 30 }], speed: 1,
        onReset: () => kLoad(kCur),
        onStep: () => {
          if (++kAcc < 60) return;
          let m = 0; for (let i = 0; i < kSim.n; i++) m += Math.abs(kSim.v[i] - kPrev[i]);
          m /= kSim.n; kPrev.set(kSim.v); kAcc = 0;
          const pos = Math.max(0, Math.min(1, (Math.log10(m + 1e-7) + 4.5) / 3.5));
          meterI.style.left = (pos * 100).toFixed(1) + '%';
          meterTxt.textContent = (m < 1.5e-3 ? 'ほとんど止まっています' : m > 8e-3 ? '動きつづけています' : '形を変えている途中です') + `（${kSim.steps} コマ目）`;
        },
      });
      kLoad(pats[0]);
      root.appendChild(step({
        title: '「完成する模様」と「生きている模様」',
        text: [
          p('模様には、2つのタイプがあります。'),
          h('ul', null,
            h('li', { html: '<b>完成する模様：</b>しばらくすると形が決まって、ほとんど動かなくなる模様。絵のように止まります。' }),
            h('li', { html: '<b>生きている模様：</b>いつまでたっても、動いたり、分かれたり、波のように走ったりしつづける模様。' })),
          p('デモで模様をえらんで動かし、「動き具合メーター」を見てみましょう。はじめは育っている途中なのでどれも動きますが、しばらく待つと差がはっきりします（「はやい」がおすすめです）。'),
          note('<p>「分裂する点」は、点が2つに分かれながら増えていきます。でも、草原が点でいっぱいになると分裂は止まり、水玉とよく似た見た目で落ち着きます。止まるかどうかは、<b>しばらく待って</b>から判断しましょう。</p>'),
        ],
        demo: [card(null, h('div', { class: 'row', style: { justifyContent: 'center', marginBottom: '8px' } }, kSeg.el), kView.el,
          h('div', { style: { margin: '10px 0 2px' } }, h('div', { class: 'ch7-meter' }, meterI), h('div', { class: 'ch7-meter-lbl' }, h('span', { text: '止まっている' }), h('span', { text: '動いている' }))),
          meterTxt, kRunner.el)],
      }));
      const kinds = ['完成する模様', '生きている模様'];
      root.appendChild(ctx.quiz({
        id: 'kind',
        type: 'match',
        q: '<p>それぞれの模様は、どちらのタイプでしょう？ デモで動かしてたしかめてから答えましょう。</p>',
        left: pats.map((pt) => `<b>${pt.name}</b>`),
        right: kinds,
        answer: pats.map((pt) => (pt.kind === 'live' ? 1 : 0)),
        hints: ['デモで1つずつ動かして、「はやい」でしばらく待ちましょう。', '動き具合メーターの針が、左（止まっている）に寄るか、右（動いている）に残るかを見ます。', `生きている模様は ${pats.filter((pt) => pt.kind === 'live').length} つだけです。いつまで待っても、メーターの針が右に残るものをさがしましょう。`],
        explain: `<p>${pats.filter((pt) => pt.kind === 'live').map((pt) => pt.name).join('、')} は生きている模様、それ以外は完成する模様です。生きている模様は、<b>いつ止めるか</b>で見た目が変わるので、好きな瞬間を写真（画像）に残すのが楽しみ方です。</p>`,
      }));

      // ---------------- 9. 再現チャレンジ ----------------
      const sp = RD.specialPoints || {};
      const start = sp.extinct || { F: (fRange[0] + fRange[1]) / 2, k: (kRange[0] + kRange[1]) / 2 };
      const cSim = newSim(128, { F: start.F, k: start.k });
      let cSeed = 'random';
      cSim.seed(cSeed);
      const cView = new RD.FieldView(cSim, { maxPx: 384 });
      const apis = {};
      let obs = 0, judged = false, selected = pats[0].id;
      const progBar = h('div'), prog = h('div', { class: 'ch7-prog' }, progBar);
      const progTxt = h('div', { class: 'readout' });
      const status = h('div', { class: 'ch7-status' });
      const solvedIds = () => pats.filter((pt) => ctx.isSolved('rep-' + pt.id)).map((pt) => pt.id);
      const goalShown = new Set(); // ヒント2を開いた模様は、地図に合格の範囲を出す
      const doneBoxes = () => pats.filter((pt) => solvedIds().includes(pt.id) || goalShown.has(pt.id))
        .map((pt) => ({ box: pt.box, label: pt.name, state: solvedIds().includes(pt.id) ? 'done' : 'goal' }));
      const cMap = new FkMap({ F: start.F, k: start.k, zoom: true, boxes: doneBoxes(), onPick: (F, k) => setFk(F, k, true) });
      const cZoom = RD.ui.segmented([{ value: 'all', label: '全体' }, { value: 'zoom', label: '拡大' }], 'zoom', (z) => cMap.setZoom(z === 'zoom'));
      const fS = numSlider({ label: '<i>F</i>', min: 0.005, max: 0.08, step: 0.0005, value: start.F, digits: 4, onInput: (v) => setFk(v, cSim.k, false), onCommit: () => commitFk() });
      const kS = numSlider({ label: '<i>k</i>', min: 0.04, max: 0.07, step: 0.0001, value: start.k, digits: 4, onInput: (v) => setFk(cSim.F, v, false), onCommit: () => commitFk() });
      const changed = () => { obs = 0; judged = false; status.innerHTML = ''; prog.classList.remove('done'); };
      function setFk(F, k, fromMap) {
        cSim.setParams({ F, k });
        if (fromMap) { fS.set(F); kS.set(k); if (cAuto.checked) cSim.seed(cSeed); }
        cMap.set(F, k);
        changed();
        cView.render(); showProg();
      }
      function commitFk() { if (cAuto.checked) { cSim.seed(cSeed); changed(); cView.render(); } }
      const cAuto = RD.ui.toggle('F, k を変えたら、種をまき直す', true);
      const seedSeg = RD.ui.segmented([{ value: 'center', label: 'まん中に1つ' }, { value: 'random', label: '数か所' }, { value: 'noise', label: 'あちこち少しずつ' }], cSeed, (v) => { cSeed = v; cSim.seed(cSeed); changed(); cView.render(); });
      function showProg() {
        const r = Math.min(1, obs / OBS_STEPS);
        progBar.style.width = (r * 100).toFixed(1) + '%';
        progTxt.textContent = r < 1 ? `観察中… ${Math.min(obs, OBS_STEPS)} / ${OBS_STEPS} コマ（F, k を変えると 0 から）` : `観察おわり（${OBS_STEPS} コマ）`;
      }
      function judgeNow() {
        judged = true;
        prog.classList.add('done');
        const st = cSim.stats();
        const hits = judge(pats, { F: cSim.F, k: cSim.k, obs, maxV: st.maxV });
        if (hits.length) {
          const names = [];
          for (const id of hits) {
            const pt = P(id);
            names.push(pt.name);
            RD.collection.add({ id: pt.id, name: pt.name, F: cSim.F, k: cSim.k, Du: cSim.Du, Dv: cSim.Dv, palette: cView.palette, thumb: cView.thumbnail(), source: 'challenge' });
            if (apis[id]) { apis[id].solve(); apis[id].feedback(`<p><b>再現できました！</b> F = ${fmt(cSim.F, 4)}, k = ${fmt(cSim.k, 4)} で「${pt.name}」ができました。コレクションに入れました。</p>`, 'ok'); }
          }
          status.innerHTML = `🎉 <b>「${names.join('」「')}」の再現に成功！</b> コレクションに入れました。`;
            cMap.setBoxes(doneBoxes());
          return;
        }
        const pt = P(selected);
        if (!(st.maxV > ALIVE_V)) {
          status.innerHTML = 'ウサギがいなくなってしまいました。地図の別の場所をえらぶか、種のまき方を変えてみましょう。';
          return;
        }
        const c = classAt(cSim.F, cSim.k), adv = advise(pt, cSim.F, cSim.k);
        status.innerHTML = `いまは<b>${c ? COUNTRIES[c].name : '地図の外'}</b>のあたりです。目標の「${pt.name}」とは少しちがうようです。` + (adv.length ? `<br>ヒント：${adv.join('、')}。` : '');
      }
      const cRunner = new RD.Runner({
        sim: cSim, autoplay: true, speeds: [{ label: 'ふつう', spf: 6 }, { label: 'はやい', spf: 16 }, { label: 'とても速い', spf: 36 }], speed: 1,
        onFrame: () => { cView.render(); showProg(); },
        onStep: () => { obs++; if (obs >= OBS_STEPS && !judged) judgeNow(); },
        onReset: () => { cSim.seed(cSeed); changed(); },
      });

      // 目標の見本（開いたときに少しずつ作る）。育つようすを4コマのパラパラ漫画で見せる。
      const FRAMES = [0.25, 0.5, 0.75, 1, 1, 1];
      const targetEls = {}, frames = {};
      const imgFor = (id) => {
        const pt = P(id);
        const el = frames[id] ? h('img', { src: frames[id][frames[id].length - 1], alt: `目標：${pt.name}` }) : h('div', { class: 'ph', text: '見本を準備中…' });
        (targetEls[id] = targetEls[id] || []).push(el);
        return el;
      };
      let genStarted = false, genRaf = 0, genCancelled = false, flip = 0;
      const flipTimer = setInterval(() => {
        flip++;
        for (const id in targetEls) {
          if (!frames[id]) continue;
          targetEls[id] = targetEls[id].filter((el) => el.isConnected);
          for (const el of targetEls[id]) if (el.tagName === 'IMG') el.src = frames[id][flip % frames[id].length];
        }
      }, 700);
      function genTargets() {
        if (genStarted) return;
        genStarted = true;
        const queue = pats.slice();
        let cur = null, gs = null, fv = null, shots = [];
        const tick = () => {
          if (genCancelled) return;
          const t0 = performance.now();
          while (performance.now() - t0 < 8) {
            if (!cur) {
              cur = queue.shift();
              if (!cur) return;
              gs = new RD.Sim({ w: 96, h: 96, F: cur.F, k: cur.k });
              gs.seed(cur.seed || 'random', seeded(7));
              fv = new RD.FieldView(gs, { readout: false, colorbar: false, maxPx: 192 });
              shots = [];
            }
            const total = cur.steps || 6000, next = Math.round(FRAMES[shots.length] * total);
            gs.step(Math.min(100, next - gs.steps));
            if (gs.steps >= next) {
              fv.render();
              const url = fv.thumbnail(144);
              while (shots.length < FRAMES.length && Math.round(FRAMES[shots.length] * total) <= gs.steps) shots.push(url);
            }
            const pct = Math.round((gs.steps / total) * 100);
            (targetEls[cur.id] || []).forEach((el) => { if (el.classList.contains('ph')) el.textContent = `見本を準備中… ${pct}%`; });
            if (shots.length >= FRAMES.length) {
              const id = cur.id, name = cur.name;
              frames[id] = shots;
              targetEls[id] = (targetEls[id] || []).map((el) => { const img = h('img', { src: shots[0], alt: `目標：${name}` }); el.replaceWith(img); return img; });
              cur = null;
            }
          }
          genRaf = requestAnimationFrame(tick);
        };
        genRaf = requestAnimationFrame(tick);
      }
      ctx.onCleanup(() => { genCancelled = true; cancelAnimationFrame(genRaf); clearInterval(flipTimer); });

      const kindTag = (pt) => h('span', { class: 'ch7-kind ' + (pt.kind === 'live' ? 'live' : 'still'), text: pt.kind === 'live' ? '生きている模様' : '完成する模様' });
      const selImg = h('div');
      const selName = h('div');
      const tSeg = RD.ui.segmented(pats.map((pt) => ({ value: pt.id, label: pt.name })), selected, (id) => select(id, false));
      function select(id, scroll) {
        selected = id;
        tSeg.set(id, false);
        const pt = P(id);
        selImg.replaceChildren(imgFor(id));
        selName.replaceChildren(h('div', { html: `目標：<b>${pt.name}</b>` }), kindTag(pt), h('div', { class: 'muted', text: DESC[id] || '' }), h('div', { class: 'muted', text: '地図の見本と見くらべて、この模様の国をさがしましょう。' }));
        status.innerHTML = '';
        if (scroll) labCard.scrollIntoView({ behavior: reduceMotion() ? 'auto' : 'smooth', block: 'start' });
      }
      const labCard = card('再現ラボ',
        h('div', { class: 'row', style: { marginBottom: '8px' } }, tSeg.el),
        h('div', { class: 'ch7-target' }, selImg, selName),
        h('div', { style: { height: '10px' } }),
        cView.el, cRunner.el,
        h('div', { style: { marginTop: '8px' } }, prog, progTxt, status),
        h('div', { class: 'ch7-ctrl' }, h('div', { class: 'row', style: { justifyContent: 'center' } }, cZoom.el), cMap.el, fS.el, kS.el,
          h('div', { class: 'muted', text: 'つまみは矢印キーでも動かせます。数の欄に直接入れることもできます。' }),
          h('div', { class: 'ch7-bar' }, h('span', { class: 'muted', text: '種：' }), seedSeg.el),
          h('div', { class: 'ch7-bar' }, cAuto.el, RD.ui.button('種をまき直す', () => { cSim.seed(cSeed); changed(); cView.render(); }, { small: true }))));
      select(selected, false);
      watch(cRunner, labCard);

      const qels = [];
      const r1 = (v, s) => fmt(Math.round(v / s) * s, 3);
      for (const pt of pats) {
        const b = pt.box;
        const seedWord = { center: 'まん中に1つ', random: '数か所', noise: 'あちこち少しずつ' }[pt.seed] || '数か所';
        const home = classAt(pt.F, pt.k);
        const qel = ctx.quiz({
          id: 'rep-' + pt.id,
          type: 'custom',
          q: `<p>「<b>${pt.name}</b>」を再現しよう</p>`,
          render(body, api) {
            apis[pt.id] = api;
            body.appendChild(h('div', { class: 'ch7-target' }, imgFor(pt.id),
              h('div', null, h('div', { html: `<b>${pt.name}</b>` }), kindTag(pt), h('div', { class: 'muted', text: DESC[pt.id] || '' }),
                h('div', { class: 'row', style: { marginTop: '8px' } }, RD.ui.button('この模様をねらう', () => select(pt.id, true), { small: true })))));
          },
          hints: [
            `地図の<b>見本</b>で、目標に似た模様が並んでいる場所をさがしましょう。` + (home ? `「<b>${COUNTRIES[home].name}</b>」のあたりです。` : '') +
              (pt.kind === 'live' || pt.seed === 'center' ? `<br>この模様は種のまき方で出かたが変わります。種は「<b>${seedWord}</b>」にしましょう。` : ''),
            (pt.hint || `F はだいたい ${r1((b.fMin + b.fMax) / 2, 0.005)}、k はだいたい ${r1((b.kMin + b.kMax) / 2, 0.0025)} のあたりです。`) + '<br>地図に、合格の範囲を<b>赤い点線の四角</b>で出しました（「拡大」で見やすくなります）。',
            `F を ${fmt(b.fMin, 4)}〜${fmt(b.fMax, 4)}、k を ${fmt(b.kMin, 4)}〜${fmt(b.kMax, 4)} のあいだにして（数の欄に直接入力できます）、${OBS_STEPS} コマ動かしましょう。`,
          ],
          answerText: `F = ${pt.F}、k = ${pt.k}（種：${seedWord}）`,
          // ヒント2を開いたら、地図に合格の範囲を出す
          onHint: (n) => { if (n >= 2 && !goalShown.has(pt.id)) { goalShown.add(pt.id); cMap.setBoxes(doneBoxes()); } },
        });
        qels.push(qel);

      }

      root.appendChild(step({
        title: '再現チャレンジ：この模様を作ろう',
        text: [
          p('いよいよ、<b>狙った模様を自分で出す</b>チャレンジです。目標の模様を1つえらび、地図やつまみで F と k を合わせましょう。'),
          h('ol', null,
            h('li', { html: '再現ラボで目標をえらぶ（各問題の「この模様をねらう」でもえらべます）' }),
            h('li', { html: '地図の<b>見本</b>と見くらべて、目標に似た模様の場所をクリック' }),
            h('li', { html: `草原を <b>${OBS_STEPS} コマ</b>動かすと判定します（青いバー）` })),
          note(`<p>F と k が目標の「国」の中に入っていれば合格です。${pats.length}つのうち<b>3つ</b>を再現すると、この章はクリアです（問題1〜5とあわせて8問）。合格した模様は、トップページの<b>コレクション</b>に入ります。</p>`),
        ],
      }));
      const repStep = step({ title: null, text: qels, demo: [labCard] });
      repStep.classList.add('ch7-rep');
      root.appendChild(repStep);
      if ('IntersectionObserver' in window) {
        const io = new IntersectionObserver((ents) => { if (ents.some((e) => e.isIntersecting)) { genTargets(); io.disconnect(); } }, { rootMargin: '600px 0px' });
        io.observe(repStep);
        ctx.onCleanup(() => io.disconnect());
      } else genTargets();

      // ---------------- まとめ ----------------
      root.appendChild(step({
        title: 'まとめ',
        text: [
          h('ul', null,
            h('li', { html: '模様ができるのは、<b>近くは仲間を増やし、遠くはじゃまをする</b>から。じゃまの正体は、速く広がる草の取り合い。' }),
            h('li', { html: '草とウサギの広がる速さが<b>同じ</b>だと、模様はできない。両方<b>ゆっくり</b>にすると、模様は<b>細かく</b>なる。' }),
            h('li', { html: '模様の<b>種類</b>は F と k（地図の国）で決まり、<b>場所や細かい形</b>は種で決まる。' }),
            h('li', { html: '模様には、<b>完成する模様</b>と<b>生きている模様</b>がある。' })),
          p('次の第8章は<b>自由ラボ</b>です。ウサギを好きな形に放したり、色を変えたりして、あなただけの模様を作りましょう。'),
          h('div', { class: 'row' }, h('a', { class: 'btn primary', href: '#/c/ch8', text: '自由ラボへ →' })),
        ],
      }));

      root.appendChild(teacher(
        '<p><b>扱うつまずき：</b>★T07（謎の回収）、T08（Du = Dv）、★T15（間隔）、★T16（F-k マップ）、T17（種と模様の種類）、T18（止まる模様と動く模様）。</p>' +
        '<p><b>問いかけの例：</b>「電車で、知らない人のすぐ隣に座る？」「消防士が火より遅かったらどうなる？」「草が速く広がるのは、ウサギにとってうれしい？ こまる？」（答え：群れの中にはうれしいが、少しはなれた場所ではこまる）</p>' +
        '<p><b>よくある反応：</b>「拡散が平らにするのに模様ができるのは矛盾」→ 1種類なら平ら、2種類がちがう速さだと模様、と区別させる。グラフで「草の谷のすそがウサギの山より外まで広がっている」ことを指でなぞらせると納得しやすいです。</p>' +
        '<p><b>電車の座席</b>のたとえは本人の体験に結びつけやすいので、最初に聞いてみてください。</p>' +
        '<p><b>再現チャレンジ：</b>判定は「F, k が目標の領域に入っていて、変えてから ' + OBS_STEPS + ' コマ動かした（ウサギが生き残っている）」ときに合格です。うずまきなど動く模様は種の置き方で出かたが変わるので、ヒント1で種の置き方も伝えています。合格領域から外れていると、地図のどちら向きに動かせばよいかを表示します。</p>' +
        '<p><b>実験の数値：</b>Du = Dv にすると、どのプリセットの値でもウサギは全滅して一様（草だけ）になりました（ウサギだらけの国に近い値では、逆に一面ウサギの一色になることもあります）。D を両方半分にすると、水玉の数は約2倍。どちらも tests/ch7.test.mjs で RD.Sim を使って確かめています。</p>'));

      ctx.onCleanup(() => { sims.length = 0; });
    },
  });
})(window.RD = window.RD || {});
